issue_context.body:
### What happens?

Using the node client, exporting a database with multiple tables works fine. Importing it fails with:

>  Invalid Error: Cannot prepare multiple statements at once!

```javascript
{
  errno: -1,
  code: 'DUCKDB_NODEJS_ERROR'
}
```



### To Reproduce

**Current OS and Node Version**

OS: MacOS Ventura 13.2 (22D49)
Device: M1 Max
Node: v18.13.0

**Steps**

```javascript
import duckdb from 'duckdb';

async function getConnection(file) {
    console.log(`creating new connection for: ${ file }`);
    return new Promise((resolve, reject) => {
        const db = new duckdb.Database(file, duckdb.OPEN_READWRITE, () => {
            resolve(db);
        });
    });
}

async function timeAsync(block) {
    const start = process.hrtime();
    await block();
    const end = process.hrtime(start);
    const elapsedMs = (end[0] * 1000000000 + end[1]) / 1000000;
    return elapsedMs;
}

async function runQuery(connection, func, sql, args) {
    args ||= [];
    func = func.bind(connection);
    return new Promise((resolve, reject) => {
        func(sql, ...args, (err, res) => {
            if (err) {
                reject(err);
                return;
            }
            resolve(res);
        });
    });
}

async function executeQuery(con, query) {
    let data = null;
    let error = null;
    const time = await timeAsync(async () => {
        try {
            data = await runQuery(con, con.all, query);
        } catch (err) {
            error = err;
        }
    });
    if (error) {
        console.log(`query failed with error`, error);
        console.log(`query executed was: ${ query }\n`);
        return;
    }
    console.log(`query executed was: ${ query }\n`);
    console.log(`query executed in ${time}ms`, data);
}

const bugCon = await getConnection("bug.db");
await executeQuery(
    bugCon,
    'create table test (id int);'
);
await executeQuery(
    bugCon,
    'create table test2 (id int);'
);
await executeQuery(
    bugCon,
    "export database './tmp' (format csv, compression zstd)"
);
console.log("creating new database to import from");
const bug2Con = await getConnection("bug2.db");

// ---------------------------------
// 🐞🐞🐞🐞THIS SHOULD WORK BUT DOESN'T
// --------------------------------

await executeQuery(
    bug2Con,
    "import database './tmp'"
);
```

